import os, re, pathlib
root = pathlib.Path(".").resolve()
moved = {root/"docs"/f"{n}.md": root/"docs"/"project"/f"{n}.md" for n in ["IMPLEMENTATION_PLAN","PROGRESS","CONFORMANCE","CODE_REVIEW","FINAL_REPORT"]}
new_to_old = {v: k for k, v in moved.items()}
LINK = re.compile(r"(\]\()([^)\s]+)(\))|^(\[[^\]]+\]:\s*)(\S+)()", re.M)
def rewrite(md):
    old_dir = new_to_old.get(md, md).parent  # where links were written from
    def fix(m):
        prefix, target, suffix = (m.group(1), m.group(2), m.group(3)) if m.group(1) else (m.group(4), m.group(5), m.group(6))
        if re.match(r"^[a-z]+:", target) or target.startswith("#"):
            return m.group(0)
        path, sep, anchor = target.partition("#")
        if not path:
            return m.group(0)
        resolved = (old_dir / path).resolve()
        resolved = moved.get(resolved, resolved)
        new = os.path.relpath(resolved, md.parent)
        if path.endswith("/") and not new.endswith("/"):
            new += "/"
        return prefix + new + sep + anchor + suffix
    text = md.read_text()
    out = LINK.sub(fix, text)
    if out != text:
        md.write_text(out); print("updated", md.relative_to(root))
for md in sorted(root.glob("**/*.md")):
    rel = md.relative_to(root)
    if any(p.startswith(".") or p in ("artifacts", "environments") for p in rel.parts):
        continue
    rewrite(md)
